function largestEvenSum(nums, k) {
  const sorted = [...nums].sort((a, b) => b - a);
  let sum = 0;
  let smallestOdd = -1;
  let smallestEven = -1;
  for (let i = 0; i < k; i++) {
    sum += sorted[i];
    if (sorted[i] % 2 === 1) {
      smallestOdd = sorted[i];
    } else {
      smallestEven = sorted[i];
    }
  }
  if (sum % 2 === 0) {
    return sum;
  }

  let largestOdd = -1;
  let largestEven = -1;
  for (let i = sorted.length - 1; i >= k; i--) {
    if (sorted[i] % 2 === 1) {
      largestOdd = sorted[i];
    } else {
      largestEven = sorted[i];
    }
  }

  let best = -1;
  if (largestEven !== -1) {
    best = Math.max(best, sum - smallestOdd + largestEven);
  }
  if (smallestEven !== -1 && largestOdd !== -1) {
    best = Math.max(best, sum - smallestEven + largestOdd);
  }
  return best;
}

