function largestEvenSum(nums, k) {
  let best = -1;
  const n = nums.length;
  for (let mask = 0; mask < (1 << n); mask++) {
    let picked = 0, total = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) { picked++; total += nums[i]; }
    if (picked === k && total % 2 === 0 && total > best) best = total;
  }
  return best;
}

