function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 10);
  const top = large ? 100000 : (rand() < 0.2 ? 100000 : 12);
  const style = rand();
  const nums = Array.from({ length: n }, () => {
    let v = Math.floor(rand() * (top + 1));
    if (style < 0.2 && v % 2 === 0) v = v === top ? v - 1 : v + 1;
    return v;
  });
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
